#define __ASSEMBLY__
#include <config.h>
#include "version_autogenerated.h"

	.global ResetEntry
	.extern entry
	.extern mmu_table_setup
#define CR_V	                     (1 << 13)	/* Vectors relocated to 0xffff0000	*/
#define HARDWARE_PAGE_TABLE_BASE     (0x80800000)


ResetEntry:
	b	reset
	ldr pc, _undefined_instruction
	ldr pc, _software_interrupt
	ldr pc, _prefetch_abort
	ldr pc, _data_abort
	ldr pc, _not_used
	ldr pc, _irq
	ldr pc, _fiq

_undefined_instruction: .word undefined_instruction
_software_interrupt:    .word software_interrupt
_prefetch_abort:    .word prefetch_abort
_data_abort:        .word data_abort
_not_used:      .word not_used
_irq:           .word irq
_fiq:           .word fiq

.global bootloader_tags
 bootloader_tags:
.long   0

#define REG_BASE_WDT 0x8200E000
reset:

        ldr r4, [r2, #4]
        ldr r5, =0x54410003
        cmp r4, r5
        beq 1f
        mov r2, r11 // r11 also holds the value of cmdline addr,
                    // so if r2 have not correct value of cmdline address(e.g
                    // debug by GDB), use r11 value

1:	str r2, bootloader_tags  // Save R2 to bootloader_tags

	// Disable Watchdog
	ldr r0, =REG_BASE_WDT
	mov r1, #0
	str r1, [r0]

	// Disable Interrupts (FIQ and IRQ), also set the cpu to SVC32 mode, except if in HYP mode already
	mrs r0, cpsr
	and r1, r0, #0x1f            // mask mode bits
	teq r1, #0x1a                // test for HYP mode
	bicne   r0, r0, #0x1f        // clear all mode bits
	orrne   r0, r0, #0x13        // set SVC mode
	orr r0, r0, #0xc0            // disable FIQ and IRQ
	msr cpsr,r0

	// Set V=0 in CP15 SCTLR register - for VBAR to point to vector
	mrc	p15, 0, r0, c1, c0, 0	 // Read CP15 SCTLR Register
	bic	r0, #CR_V		@ V = 0
	mcr	p15, 0, r0, c1, c0, 0	 // Write CP15 SCTLR Register

	// Set vector address in CP15 VBAR register
	ldr	r0, =ResetEntry
	mcr	p15, 0, r0, c12, c0, 0	 // Set VBAR

	mov	r4,#0xffffffff
	mcr	p15,0,r4,c3,c0,0        // domain
	// Invalidate TLB
	mov     r0, #0
	mcr     p15, 0, r0, c8, c7, 0   // Invalidate entire unified TLB
	mcr     p15, 0, r0, c8, c6, 0   // Invalidate entire data TLB
	mcr     p15, 0, r0, c8, c5, 0   // Invalidate entire instruction  TLB

mmu_set:
	// Set Table Base Control Register
	mov     r0, #0
	mcr     p15, 0, r0, c2, c0, 2

	bl mmu_table_setup
	// Page table modifications
	// Stored in memory is a set of page tables that flat-maps memory
	#ldr     r0, =HARDWARE_PAGE_TABLE_BASE        // Location of master copy of TTB
	// Set location of L1 page table
	#mcr     p15, 0, r0, c2, c0, 0


	mrc p15, 0, r0, c1, c0, 1 // Read Auxiliary Control Register
	orr r0,  #0x40            // enable SMP bit
	mcr p15, 0, r0, c1, c0, 1 // Write Auxiliary Control Register

	// enable mmu
	dsb
	mrc     p15, 0, r0, c1, c0, 0       // Read SCTLR - System Control Register
	orr     r0, r0, #0x01               // Set M bit (bit 0)
	mcr     p15, 0, r0, c1, c0, 0       // Write SCTLR
	isb

	// enable cache
	mrc     p15, 0, r0, c1, c0, 0       // Read System Control Register configuration data
	orr     r0, r0, #0x0004             // Set C bit
	orr     r0, r0, #0x1000             // Set I bit
	mcr     p15, 0, r0, c1, c0, 0       // Write System Control Register configuration data


	#--- Initialise stack register, stack_base is __text_start__
	ldr     r0, =STACK_TOP_ADDR
	mov     sp, r0
	mrs r0, cpsr
	bic r0, r0, #0xc0            // enable FIQ and IRQ
	msr cpsr,r0
	b main

/*
 * exception handlers
 */
undefined_instruction:
software_interrupt:
prefetch_abort:
data_abort:
not_used:
	b .

@
@ IRQ stack frame.
@

#define IRQ_STACK_START  (IRQ_STACK_TOP_ADDR - 4)
#define FIQ_STACK_START  (IRQ_STACK_START - CONFIG_STACKSIZE_IRQ)

#define S_PC		60
#define S_FRAME_SIZE	72
/*
 * use bad_save_user_regs for abort/prefetch/undef/swi ...
 * use irq_save_user_regs / irq_restore_user_regs for IRQ/FIQ handling
 */
	.macro	irq_save_user_regs
	sub	sp, sp, #S_FRAME_SIZE
	stmia	sp, {r0 - r12}			@ Calling r0-r12
	@ !!!! R8 NEEDS to be saved !!!! a reserved stack spot would be good.
	add	r8, sp, #S_PC
	stmdb	r8, {sp, lr}^		@ Calling SP, LR
	str	lr, [r8, #0]		@ Save calling PC
	mrs	r6, spsr
	str	r6, [r8, #4]		@ Save CPSR
	str	r0, [r8, #8]		@ Save OLD_R0
	mov	r0, sp
	.endm

	.macro	irq_restore_user_regs
	ldmia	sp, {r0 - lr}^			@ Calling r0 - lr
	mov	r0, r0
	ldr	lr, [sp, #S_PC]			@ Get PC
	add	sp, sp, #S_FRAME_SIZE
	subs	pc, lr, #4		@ return & move spsr_svc into cpsr
	.endm

	.macro get_irq_stack			@ setup IRQ stack
	ldr	sp, =IRQ_STACK_START
	.endm

	.macro get_fiq_stack			@ setup FIQ stack
	ldr	sp, =FIQ_STACK_START
	.endm

/*
 * exception handlers
 */
	.align	5
irq:
	get_irq_stack
	irq_save_user_regs
	bl	gx_irq_handler
	irq_restore_user_regs

	.align	5
fiq:
	get_fiq_stack
	/* someone ought to write a more effiction fiq_save_user_regs */
	irq_save_user_regs
	bl	gx_fiq_handler
	irq_restore_user_regs
	.end

